from ute_core.exception import CoreException


class TestlineConfigurationException(CoreException):
    """Base exception class for the testline_configuration library."""


class ConfigNotValid(TestlineConfigurationException):
    """Exception raised when any Config object contains an error."""


class ConfigVariableDoesNotExist(TestlineConfigurationException):
    """Exception raised when the CONFIGURATION variable does not exist."""


class CannotImportConfig(TestlineConfigurationException):
    """Exception raised when the library cannot import the specified module/package."""


class WrongSchemaIndex(TestlineConfigurationException):
    """Exception raised when index of config schema in Linker is incorrect."""
